// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, address _adversaryActor) public {
        vm.assume(_value <= address(c).balance + 1 ether);
        vm.prank(_adversaryActor);
        ComplexFallbackReceiver receiver = new ComplexFallbackReceiver();
        vm.deal(address(c), _value + 1 ether);
        vm.prank(c.owner());
        bool okRef;
        try c.sendMoney(address(receiver), _value) {
            okRef = true;
        } catch {
            okRef = false;
        }
        assertTrue(okRef);
    }
}

contract ComplexFallbackReceiver {
    fallback() external payable {
        uint256 x = gasleft();
        for (uint i = 0; i < 10; i++) {
            assembly {
                sstore(0, x)
            }
        }
    }
}
